// Page language. lang.js picks it before first paint and sets <html lang>; this module reads it. English is the source:
// t("English text", ...args) looks the text up in lib/app/i18n/<lang>.js (keyed by the English, first argument always a
// "double-quoted" literal so tests can find it), fills {0}, {1}… with args and writes numeric args the local way.
// Car text is translated per stop in stops/<slug>/<lang>.js: car.js's shape, strings only, merged over it by loadCar.
export const LANGS = ["en", "hu"];
const STORE = "tour-lang";   // also read by lang.js
export const lang = LANGS.includes(globalThis.document?.documentElement.lang) ? document.documentElement.lang : "en";
const catalog = lang === "en" ? null : (await import(`./i18n/${lang}.js`)).default;
export const missing = new Set();   // keys with no translation; ?debug exposes them and the e2e tests check it is empty

// A number (as toFixed gives it) written the local way: decimal comma in Hungarian. Other text passes unchanged.
export const num = v => (lang !== "en" && /^[-−]?\d+\.\d+$/.test(String(v)) ? String(v).replace(".", ",") : String(v));

export function t(text, ...args) {
  let out = text;
  if (catalog) { out = catalog[text]; if (out === undefined) { missing.add(text); out = text; } }
  return args.length ? out.replace(/\{(\d)\}/g, (_, i) => num(args[i])) : out;
}

// Overlay a translation on a car config: objects key by key, arrays item by item; null or a missing item keeps the original.
export function merge(base, over) {
  if (over == null) return base;
  if (Array.isArray(base) && Array.isArray(over)) return base.map((b, i) => merge(b, over[i]));
  if (base && typeof base === "object" && !Array.isArray(base) && typeof over === "object" && !Array.isArray(over)) {
    const out = { ...base };
    for (const k of Object.keys(over)) out[k] = merge(base[k], over[k]);
    return out;
  }
  return over;
}

// slug must already be checked against stops/tour.js.
export async function loadCar(slug) {
  const car = (await import(`../../stops/${slug}/car.js`)).default;
  return lang === "en" ? car : merge(car, (await import(`../../stops/${slug}/${lang}.js`)).default);
}

// Static page text (elements marked data-i18n hold their English text as the key) and the EN/HU switch in the header bar.
export function localizePage() {
  for (const el of document.querySelectorAll("[data-i18n]")) el.textContent = t(el.textContent.trim().replace(/\s+/g, " "));
  document.documentElement.classList.remove("translating");
  for (const b of document.querySelectorAll("[data-lang]")) {
    b.setAttribute("aria-pressed", String(b.dataset.lang === lang));
    b.addEventListener("click", () => {
      if (b.dataset.lang === lang) return;
      try { localStorage.setItem(STORE, b.dataset.lang); } catch { /* storage blocked: the reload falls back to the default */ }
      location.reload();
    });
  }
}
// Picks the page language before first paint (a classic script in <head>): the visitor's saved choice, else the browser's
// language. It sets <html lang>, which lib/app/i18n.js reads, and hides marked static text until it is translated.
(function () {
  var lang = null;
  try { lang = localStorage.getItem("tour-lang"); } catch (e) { /* storage blocked: fall back to the browser language */ }
  if (lang !== "en" && lang !== "hu") lang = /^hu\b/i.test(navigator.language || "") ? "hu" : "en";
  document.documentElement.lang = lang;
  if (lang !== "en") document.documentElement.classList.add("translating");
})();
// Service-worker registration shared by the index and every stop. On localhost / LAN addresses the SW is skipped (and any
// earlier one removed) so dev edits are never served stale; add ?sw=1 to test offline locally against a build in _site/.
import { t } from "./i18n.js";

const LOCAL = /^(localhost|127\.|\[::1\]|10\.|192\.168\.|172\.(1[6-9]|2\d|3[01])\.)|\.local$/;

// onStatus(kind, info): kind = "ready" | "partial" | "dev" | "unsupported" | "error"; info = { version, total, cached }.
export function registerOffline(onStatus = () => {}) {
  if (!("serviceWorker" in navigator)) return onStatus("unsupported");
  const sw = navigator.serviceWorker;
  if (LOCAL.test(location.hostname) && !new URLSearchParams(location.search).has("sw")) {
    sw.getRegistrations().then(rs => rs.forEach(r => r.unregister()));
    return onStatus("dev");
  }
  const root = new URL("../../", import.meta.url);   // site root, where sw.js lives
  sw.register(new URL("sw.js", root)).then(() => sw.ready).then(reg => new Promise(resolve => {
    const ch = new MessageChannel();
    ch.port1.onmessage = e => resolve(e.data);
    reg.active.postMessage({ type: "status" }, [ch.port2]);
  })).then(s => onStatus(s.total > 0 && s.cached === s.total ? "ready" : "partial", s)).catch(err => { console.warn(err); onStatus("error"); });
}

// The route pages' status line (index.html, teaser.html): what registerOffline reports, asked again while files are stored.
export function showOfflineStatus(el) {
  registerOffline(function show(kind, s) {
    el.textContent = {
      ready: t("Ready offline ✓ — every stop is stored on this device."),
      partial: t("Storing the tour for offline use… ({0} of {1} files)", s?.cached ?? 0, s?.total ?? "?"),
      dev: t("Offline mode is off on this development server (add ?sw=1 to a built copy to test it)."),
      unsupported: t("This browser cannot store the tour offline; keep a signal."),
      error: t("Offline storage failed; the tour still works with a signal. Reload to retry."),
    }[kind];
    el.classList.toggle("ready", kind === "ready");
    if (kind === "partial") setTimeout(() => registerOffline(show), 1500);
  });
}

// Route page (index.html): the stops grouped by room in walking order as photo cards, a jump list to the rooms (native
// fragment links), plus offline status. Each card is one link: photo, familiar name, year and the car's question (its
// summary until it has one). Car configs are pure data, so this imports them without loading three.js. teaser.html has
// its own page script, teaser.js.
import tour from "../../stops/tour.js";
import { showOfflineStatus } from "./offline.js";
import { t, loadCar, localizePage } from "./i18n.js";

localizePage();
showOfflineStatus(document.getElementById("status"));

const route = document.getElementById("route");
const cars = await Promise.all(tour.map(s => loadCar(s.slug)));
const rooms = [];
tour.forEach((s, i) => {
  const key = `${s.room} · Level ${s.level}`;
  if (rooms.at(-1)?.key !== key) rooms.push({ key, id: `room-${s.room.toLowerCase().replace(/[^a-z0-9]+/g, "-")}`, name: s.room, level: s.level, stops: [] });
  rooms.at(-1).stops.push({ s, car: cars[i], n: i + 1 });
});

const el = (tag, cls, text) => { const e = document.createElement(tag); if (cls) e.className = cls; if (text != null) e.textContent = text; return e; };
const levelNote = room => (room.stops.some(({ s }) => s.check === "level") ? ` · ${t("level not yet checked")}` : "");

const jump = document.getElementById("jump");
jump.querySelector("ul").replaceChildren(...rooms.map(room => {
  const a = el("a", "pill"); a.href = `#${room.id}`;
  a.append(el("span", null, t(room.name)), el("small", null, t("Level {0}", room.level)));
  const li = el("li"); li.append(a); return li;
}));
jump.hidden = false;

route.replaceChildren(...rooms.map(room => {
  const li = el("li", "room"), head = el("div", "room-head"), count = room.stops.length;
  li.id = room.id;
  head.append(el("h2", null, t(room.name)), el("span", null, (count === 1 ? t("Level {0} · 1 stop", room.level) : t("Level {0} · {1} stops", room.level, count)) + levelNote(room)));
  const ul = el("ul", "stops");
  for (const { s, car, n } of room.stops) {
    const a = document.createElement("a"); a.href = `stop.html?s=${s.slug}`;
    if (car.photo) {   // decorative inside the link: the car's name is the link text
      const img = Object.assign(document.createElement("img"), { src: `stops/${s.slug}/${car.photo.src}`, alt: "", width: car.photo.w, height: car.photo.h, loading: "lazy", decoding: "async" });
      const pic = el("div", "pic"); pic.append(img); a.append(pic);
    }
    const pill = el("span", "pill primary", t("See it working"));
    const arrow = el("i", null, "›"); arrow.setAttribute("aria-hidden", "true"); pill.append(arrow);
    const text = el("div", "text");
    text.append(el("small", null, t("Stop {0} · {1}", n, car.year)), el("b", null, car.name), el("p", car.question ? "question" : null, car.question ?? car.summary));
    if (car.photo?.caption) text.append(el("p", "caption", car.photo.caption));
    if (s.check === "room") text.append(el("p", "caption", t("Room not yet checked: it may stand elsewhere")));
    text.append(pill);
    a.append(text);
    const item = el("li", "stop"); item.append(a); ul.append(item);
  }
  li.append(head, ul);
  return li;
}));

// Photo credits from the car data, so the line stays true as stops are added.
const credits = [...new Set(cars.filter(c => c.photo).map(c => `${c.photo.credit.author} (${c.photo.credit.license})`))];
document.getElementById("credits").textContent = t("Photos via Wikimedia Commons: {0}; each stop links its photo's source.", credits.join(", "));

// The rooms exist only now: a link from another page to one of them (index.html#room-legend-6) lands here.
if (location.hash.startsWith("#room-")) document.getElementById(location.hash.slice(1))?.scrollIntoView();
// Page shell for every stop: stop.html?s=<slug>[&r=teaser]. Builds the page from stops/tour.js + stops/<slug>/car.js: the
// car's scroll story (story.js), where it is on the route, and prev/next.
// With r=teaser (links from teaser.html) prev/next, the stop count and the back link stay within the teaser.
import tour, { teaser } from "../../stops/tour.js";
import { registerOffline } from "./offline.js";
import { t, loadCar, localizePage, missing } from "./i18n.js";
import { h, link } from "./dom.js";
import { story, play } from "./story.js";

const params = new URLSearchParams(location.search);
const slug = params.get("s");
const teaserStops = tour.filter(s => teaser.includes(s.slug));
const inTeaser = params.get("r") === "teaser" && teaserStops.some(s => s.slug === slug);
const route = inTeaser ? teaserStops : tour;
const idx = route.findIndex(s => s.slug === slug);   // validated before any dynamic import
const app = document.getElementById("app");

localizePage();
registerOffline();
if (inTeaser) Object.assign(document.getElementById("back"), { href: "teaser.html", textContent: t("← Highlights") });
if (idx < 0) {
  document.title = t("Stop not found · Museum tour");
  app.replaceChildren(h("h1", {}, t("Stop not found")), h("p", {}, t("This QR code or link does not match a stop on the tour."), " ", link("./", t("Open the tour route"))));
} else {
  main().catch(err => {
    console.error(err);
    app.append(h("p", { class: "fail" }, t("The 3D view could not load. Check your connection and reload the page; after one visit with signal it also works offline.")));
  });
}

async function main() {
  const stop = route[idx];
  const car = await loadCar(stop.slug);
  document.title = t("{0} · Museum tour", car.name);
  const prev = route[idx - 1], next = route[idx + 1], here = s => `stop.html?s=${s.slug}${inTeaser ? "&r=teaser" : ""}`;
  const nameOf = async s => (s ? (await loadCar(s.slug)).name : null);
  const [prevName, nextName] = await Promise.all([nameOf(prev), nameOf(next)]);
  const s = story(car, { title: "h1" });
  document.getElementById("where").textContent = t("Stop {0} of {1} · {2} · Level {3}", idx + 1, route.length, t(stop.room), stop.level)
    + (stop.check ? ` · ${stop.check === "level" ? t("level not yet checked") : t("room not yet checked")}` : "");
  app.replaceChildren(s.el,
    h("nav", { class: "pager", "aria-label": t("Previous and next stop") },
      prev ? link(here(prev), `← ${prevName}`) : h("span"), next ? link(here(next), `${nextName} →`) : h("span")),
    h("p", { class: "note" }, t("Unofficial private tour notes, not affiliated with Mercedes-Benz. 3D: three.js (MIT). Mechanisms are original code from illustrative hardpoints.")));
  const handles = await play([s]);
  if (params.has("debug")) window.__tour = { stories: handles, missing: () => [...missing], ready: true };
}
// Teaser page (teaser.html): the teaser stops as scroll stories (story.js), one after the other. Each story links its stop
// page with &r=teaser, so the stop pages page between these stops.
import tour, { teaser } from "../../stops/tour.js";
import { showOfflineStatus } from "./offline.js";
import { t, loadCar, localizePage, missing } from "./i18n.js";
import { h } from "./dom.js";
import { story, play } from "./story.js";

localizePage();
showOfflineStatus(document.getElementById("status"));
const cars = await Promise.all(tour.filter(s => teaser.includes(s.slug)).map(s => loadCar(s.slug)));
const credits = [...new Set(cars.filter(c => c.photo).map(c => `${c.photo.credit.author} (${c.photo.credit.license})`))];
document.getElementById("credits").textContent = t("Photos via Wikimedia Commons: {0}; each car's page links its photo's source.", credits.join(", "));

const stories = cars.map(car => story(car, { more: h("a", { class: "pill primary", href: `stop.html?s=${car.slug}&r=teaser` }, t("Open this car on its own page")) }));
document.getElementById("cars").replaceChildren(...stories.map(s => s.el));
const handles = await play(stories);
if (new URLSearchParams(location.search).has("debug")) window.__tour = { stories: handles, missing: () => [...missing], ready: true };

// Scroll stories, shared by stop.html (shell.js: one car) and teaser.html (teaser.js: the teaser cars). Scrolled to, a car's
// stage (museum photo / 3-D model) pins, above the steps on a phone held upright and beside them otherwise, and only the
// steps move on: the introduction over the museum photo (with car.look, the one thing to find on the exhibit), one step
// per component in 3D, then background back on the photo with the car outline (car.takeaway first). A component step reads
// as one experiment: its prompt, the mechanism's key cards, its answer, a photo of the real part where the exhibit hides it
// (component.real), then the rest under a disclosure named by component.more (panel.js `detail`); without `more` its cards
// and technical facts follow in order. The step at the reading line sets what the stage shows; only stages on screen run
// their frame loop. Tapping a real-part photo swaps it with the stage, for a close look; tapping either again, or scrolling
// the photo's place out of view, swaps them back.
import { t } from "./i18n.js";
import { h, link } from "./dom.js";
import { stageElement, mountViewer, caveats } from "./viewer.js";

// A step is its content and what the stage shows while it is at the reading line.
const step = (state, ...kids) => ({ state, el: h("section", { class: "step" }, kids) });
// What to look at on the real car, before the model and after it.
const look = (label, text) => (text ? h("p", { class: "look" }, h("b", {}, label), " ", text) : null);

// The mechanism in real life (component.real): a photo of the same kind of part, for one this exhibit hides.
// Its picture is a button that swaps it with the stage (story's `swap`).
const real = r => (r ? h("figure", { class: "real" },
  h("div", { class: "real-media", "data-back": t("Tap the 3D view to swap back") },
    h("button", { type: "button", class: "real-open", "aria-label": t("Show this photo large, in place of the 3D view") },
      h("img", { src: r.src, alt: r.alt, width: r.w, height: r.h, loading: "lazy", decoding: "async" }))),
  h("figcaption", {}, h("b", {}, t("In real life:")), " ", r.caption, " ",
    h("span", { class: "credit" }, t("Photo:"), " ", link(r.credit.url, r.credit.author), `, ${r.credit.license}`))) : null);

// A component's step, with the elements its panel cards go into.
function compStep(c) {
  const main = h("div", { class: "cards" }), detail = c.more ? h("div", { class: "cards" }) : main;
  const st = step({ comp: c.id, view: "model", outline: false }, h("h3", {}, c.label),
    c.prompt ? h("p", { class: "prompt" }, c.prompt) : null, main, c.answer ? h("p", { class: "answer" }, c.answer) : null,
    real(c.real), c.more ? h("details", { class: "more" }, h("summary", {}, c.more), detail) : null);
  return { ...st, slots: { main, detail } };
}

// One car's story, not yet playing. title: the tag of the car's title ("h1" on its own page); more: what closes the
// background step (the teaser's link to the stop page).
export function story(car, { title = "h2", more = null } = {}) {
  const first = car.components[0].id;
  const comps = car.components.map(compStep);
  const steps = [
    step({ comp: first, view: "photo", outline: false }, h("div", { class: "eyebrow" }, car.eyebrow), h(title, {}, car.title), h("p", { class: "lede" }, car.lede),
      look(t("At the car:"), car.look)),
    ...comps,
    step({ comp: first, view: "photo", outline: true }, look(t("Back at the car:"), car.takeaway), h("footer", {}, h("h3", {}, t("Background")),
      h("p", {}, t("Back on the museum photo: the mechanism where it sits, inside the car's outline.")),
      car.note ? h("p", {}, car.note) : null, ...caveats(car), more)),
  ];
  steps[0].el.classList.add("on");
  const stageEl = stageElement(car);
  const el = h("article", { class: "story", "aria-label": car.name }, h("div", { class: "story-stage" }, stageEl), h("div", { class: "steps" }, steps.map(s => s.el)));
  return { car, el, stageEl, steps, comps, at: 0, viewer: null, ...swapper(el, stageEl) };
}

// A real-part photo and the stage change places: the photo's button goes where the stage was (pinned, in the stage's box, so
// nothing below moves) and the stage
// into the photo's place in its step. One swap per story at a time. Tapping the big photo or the small stage (a tap, not an
// orbit drag or pinch) swaps back; so does check(), called on scroll, once the photo's place is out of view (above the
// pinned stage area or below the screen).
function swapper(el, stageEl) {
  let media = null;   // the .real-media now holding the stage
  const back = () => {
    if (!media) return;
    const btn = el.querySelector(".story-stage .real-open");
    btn.replaceWith(stageEl); media.append(btn); btn.removeAttribute("style");
    btn.setAttribute("aria-label", t("Show this photo large, in place of the 3D view"));
    media.classList.remove("swapped"); media = null;
  };
  const swap = m => {
    back();
    const btn = m.querySelector(".real-open");
    btn.setAttribute("style", stageEl.getAttribute("style") ?? "");   // the stage's aspect: the pinned area keeps its size
    stageEl.replaceWith(btn); m.append(stageEl);
    btn.setAttribute("aria-label", t("Put the photo back and show the 3D view"));
    m.classList.add("swapped"); media = m;
  };
  for (const btn of el.querySelectorAll(".real-open")) {
    btn.addEventListener("click", () => (btn.closest(".real-media") ? swap(btn.closest(".real-media")) : back()));
  }
  // A tap on the stage while it is small: one pointer, barely moved.
  const downs = new Map();
  stageEl.addEventListener("pointerdown", e => downs.set(e.pointerId, [e.clientX, e.clientY, downs.size === 0]));
  stageEl.addEventListener("pointercancel", e => downs.delete(e.pointerId));
  stageEl.addEventListener("pointerup", e => {
    const d = downs.get(e.pointerId); downs.delete(e.pointerId);
    if (media && d?.[2] && downs.size === 0 && Math.hypot(e.clientX - d[0], e.clientY - d[1]) < 8) back();
  });
  const check = pane => {
    if (!media) return;
    const r = media.getBoundingClientRect(), beside = r.left >= pane.right;
    if (r.bottom < (beside ? 0 : pane.bottom) || r.top > innerHeight) back();
  };
  return { swap, back, check, swapped: () => !!media };
}

// Loads the stories' 3-D views (already in the page) and lets the scroll drive them. Returns one ?debug handle per story.
export async function play(stories) {
  await Promise.all(stories.map(async s => {
    try {
      s.viewer = await mountViewer(s.car, s.stageEl, comp => s.comps[s.car.components.indexOf(comp)].slots);
      s.viewer.show(s.steps[0].state);
    } catch (err) {
      console.error(err);
      s.stageEl.after(h("p", { class: "fail" }, t("The 3D view could not load. Check your connection and reload the page; after one visit with signal it also works offline.")));
    }
  }));

  // The reading line: halfway down the screen beside the pinned stage, or halfway down the part it leaves free below it.
  // The last step whose top has passed the line is the one shown.
  function pick() {
    for (const s of stories) {
      const pane = s.el.querySelector(".story-stage").getBoundingClientRect(), beside = s.steps[0].el.getBoundingClientRect().left >= pane.right;
      s.check(pane);
      const line = beside ? innerHeight / 2 : (pane.bottom + innerHeight) / 2;
      let at = 0;
      s.steps.forEach((st, i) => { if (st.el.getBoundingClientRect().top < line) at = i; });
      if (at === s.at) continue;
      const before = s.steps[s.at].state;
      s.at = at;
      s.steps.forEach((st, i) => st.el.classList.toggle("on", i === at));
      if (s.viewer && s.steps[at].state !== before) s.viewer.show(s.steps[at].state);
    }
  }
  let queued = false;
  const schedule = () => { if (!queued) { queued = true; requestAnimationFrame(() => { queued = false; pick(); }); } };
  addEventListener("scroll", schedule, { passive: true });
  addEventListener("resize", schedule);
  pick();

  // Only stages on screen animate: several scenes at once, one of them a live wind tunnel, would be too much for a phone.
  const onScreen = new IntersectionObserver(entries => {
    for (const e of entries) { const v = stories.find(s => s.stageEl === e.target).viewer; if (e.isIntersecting) v.start(); else v.stop(); }
  });
  for (const s of stories) if (s.viewer) onScreen.observe(s.stageEl);

  return stories.map(s => ({
    slug: s.car.slug, step: () => s.at, state: () => s.viewer?.state, swapped: s.swapped,
    frames: () => s.viewer?.stage.stats.frames ?? 0, triangles: () => s.viewer?.stage.renderer.info.render.triangles ?? 0,
  }));
}

// The Hungarian tour: a hu-HU browser gets Hungarian on its first visit, no stop shows untranslated text, numbers use a
// decimal comma, and the EN/HU switch is remembered. One device is enough: smoke.spec covers layout on all of them.
import { test, expect } from "@playwright/test";
import tour, { teaser } from "../../stops/tour.js";
import { merge } from "../../lib/app/i18n.js";
import hu from "../../lib/app/i18n/hu.js";
import { watchErrors } from "./helpers.mjs";

const cars = await Promise.all(tour.map(async s =>
  merge((await import(`../../stops/${s.slug}/car.js`)).default, (await import(`../../stops/${s.slug}/hu.js`)).default)));

test.use({ locale: "hu-HU" });
test.beforeEach(() => test.skip(test.info().project.name !== "iphone", "one device covers the translation"));

for (const car of cars) {
  test(`${car.slug} in Hungarian`, async ({ page }) => {
    const errors = watchErrors(page);
    await page.goto(`stop.html?s=${car.slug}&debug`);
    await page.waitForFunction(() => window.__tour?.stories[0].frames() > 10, null, { timeout: 20_000 });
    await expect(page.locator("html")).toHaveAttribute("lang", "hu");
    await expect(page.locator("h1")).toHaveText(car.title);
    await expect(page.locator(".step h3")).toHaveText([...car.components.map(c => c.label), hu["Background"]]);

    await page.locator(".step").nth(1).evaluate(s => s.scrollIntoView({ block: "center" }));   // the first component in 3D
    await expect.poll(() => page.evaluate(() => window.__tour.stories[0].state().view)).toBe("model");
    const frames = await page.evaluate(() => window.__tour.stories[0].frames());
    await page.waitForFunction(f => window.__tour.stories[0].frames() > f + 10, frames);

    const shown = await page.locator(".panel output, .panel .badge").allTextContents();
    expect(shown.filter(s => /\d\.\d/.test(s)), "decimal comma").toEqual([]);
    expect(await page.evaluate(() => window.__tour.missing())).toEqual([]);
    expect(errors).toEqual([]);
  });
}

test("index in Hungarian; the switch changes language and is remembered", async ({ page }) => {
  const errors = watchErrors(page);
  await page.goto("./");
