  const [r0, r1, nf] = F.rake, M = Math.ceil(nx / (U * GAP)) + 2;
  const seedJ = Array.from({ length: nf }, (_, f) => (r0 + (r1 - r0) * f / (nf - 1)) / F.cell - 0.5);
  const pi = new Float32Array(nf * M), pj = new Float32Array(nf * M), born = new Int32Array(M);
