  for (let s = 0; s < M; s++) {                    // start as a uniform stream: straight filaments, oldest furthest back
    const age = (head - s + M) % M; born[s] = -age;
    for (let f = 0; f < nf; f++) {                 // none inside the body: the still air there would hold them for good
      const i = 1.5 + age * U * GAP, inside = i < nx && grid.solid[Math.round(seedJ[f]) * nx + Math.round(i)];
      pi[f * M + s] = inside ? nx : i; pj[f * M + s] = seedJ[f];
