  function stopDemo() { if (demo) { demo = false; ui.toggle("auto").set(false); } }
  function operate(c) {
    const out = (sys.pos.get(c.id) ?? 0) > 0.5;
    sys.use(c.id, c, out ? -1 : 1);
    p.consumers.forEach(q => ui.toggle(q.id).set(q === c));
