    update(dt) {
      if (demo && !sys.moving) { wait -= dt; if (wait <= 0) { operate(p.consumers[k]); k = (k + 1) % p.consumers.length; wait = 1.2; } }
      for (let n = 0, h = Math.min(dt, 0.1) / 10; n < 10; n++) sys.step(h);
